class BuilderSegment:
    """Anything that handles instructions in the context of the build process"""

    _CLSNAME_PREFIX = "_SEGMENT_"
    _IDENTIFIER = "_GENERIC_"
    _VERSN = 0
    _BUILD = 0

    def __init__(self, **params):
        self._params: Dict[str, Any] = params
        self._welcome_log()

    def _welcome_log(self):
        info(*self._welcome_log_lines())

    def _welcome_log_lines(self):
        version, build = type(self)._VERSN, type(self)._BUILD
        yield (
            f"Hello from {type(self)._CLSNAME_PREFIX} "
            + f"'{type(self)._IDENTIFIER}'"
            + f" (v{version}.{build})"
        )
        yield from self._detail_log_lines()

    def _detail_log_lines(self):
        if self._params:
            yield f"parameters ({len(self._params)}):"
            for param, value in self._params.items():
                yield f"  - {param}={value}"
        else:
            yield "[no parameters given]"

    @property
    def identifier(self):
        """access the identifier"""
        return type(self)._IDENTIFIER

    @classmethod
    def __init_subclass__(
        cls,
        identifier=None,
        version=None,
        build=None,
    ):
        if identifier is None:
            identifier = cls.__name__.upper()
        cls._IDENTIFIER = identifier
        if version is not None:
            cls._VERSN = version
        if build is not None:
            cls._BUILD = build


class Optimizer(BuilderSegment):
    """Optimize the instruction tree w.r.t. certain aspects"""

    def __str__(self):
        param_string = "|".join(
            [f"{key}={val}" for key, val in self._params.items()]
        )
        return f"<{self._CLSNAME_PREFIX}.{self.identifier}: {param_string}>"

    def __repr__(self):
        # param_string = "|".join(
        #     [f"{key}={val}" for key, val in self._params.items()]
        # )
        return f"<{self._CLSNAME_PREFIX}.{self.identifier}>"

    @log.wrap_call
    def apply(self, instruction, **extra_args):
        """apply the optimizer"""
        raise NotImplementedError(
            "apply method must be implemented in subclass"
        )


class ValidationError(Exception):
    """An Error exception class thrown from validator"""


class Validator(BuilderSegment):
    """Validators check whether an instruction tree matches all requirements"""

    _CLSNAME_PREFIX = "VALIDATOR"

    def validate(self, instruction, report, **extra_args):
        """apply the validator to an instruction tree"""
        # check if all requirements are fulfilled
        return True

    def handle_fail(self, details, report, **extra_args):
        """raise an exception from the tree"""
        return ValidationError(details)


class Builder(BuilderSegment, identifier="GENERIC"):
    """
    Make codecontainer from instruction tree.

    Builders primarily build routines, but they can also combine them to libraries.

    As another builder might be used for various routines that end up in the same
    library, it might be cool to build routines in a capture container and rerise the
    captured variables once the routine has been included in a library. Has the
    theoretical possiblity to screw up the levels, but that's gonna be ok.

    To circumvent that, I will for now require, that built routines are in libraries
    already. A Library-Container will have routines that can be called by any builder
    to attach more routines to it, therefore breaking out of the familiar builder
    structure.

    The Library class will manage that from there on and provide library objects
    providing routines, that in turn can be imported if the signatures match.
    """

    _CLSNAME_PREFIX = "Builder"
    _IDENTIFIER = "DEFAULT"
    _BCKND = "GENERIC"

    _supp_instr_handler: Dict[type, Generator] = {}
    _excl_instr_classes: Set[type] = set()

    # _comment_cls = CommentLine
    _assignment_class = AssignmentLine
    _routinecall_class = RoutineCallContainer
    _kernelcall_class = KernelCallContainer
    _extimport_class = ExternalImport
    _mfcontainer_class = MultiFrameContainer

    def __init_subclass__(cls, **kwargs):
        super().__init_subclass__(**kwargs)
        cls.set_default_handlers()

    def __init__(
        self,
        name,
        makefile=None,
        extra_instr_handler=None,
        avoid_instr_classes=None,
        **params,
    ):
        self._name = name
        self._makefile = makefile

        if extra_instr_handler is None:
            extra_instr_handler = {}
        if avoid_instr_classes is None:
            avoid_instr_classes = set()
        self._extra_instr_handler: Dict[type, Generator] = extra_instr_handler
        self._avoid_instr_classes: Set[type] = avoid_instr_classes

        super().__init__(**params)

    # def initialize_makefile(self, name, **kwargs):
    #     """initialize a new makefile"""
    #     return MakeFileManager(name, **kwargs)

    @property
    def makefile(self):
        """access the read-only attribute makefile"""
        return self._makefile

    def _detail_log_lines(self):
        yield f"Builder name: {self._name}"
        yield from BuilderSegment._detail_log_lines(self)
        supported = list(type(self)._supp_instr_handler.keys())
        if supported:
            yield f"supported ({len(supported)}):"
            for instruction_type in supported:
                yield f"  + {instruction_type.class_identifier()}"
        excluded = list(type(self)._excl_instr_classes)
        if excluded:
            yield f"excluded ({len(excluded)}):"
            for instruction_type in excluded:
                yield f"  - {instruction_type}"

        additional = list(self._extra_instr_handler.keys())
        if additional:
            yield f"additional ({len(additional)}):"
            for instruction_type in additional:
                yield f"  + {instruction_type.class_identifier()}"
        forbidden = list(self._avoid_instr_classes)
        if forbidden:
            yield f"forbidden ({len(forbidden)}):"
            for instruction_type in forbidden:
                yield f"  - {instruction_type}"

    def add_supported_instruction_class(self, instruction_class, handler):
        """add a supported instruction class and its handler"""
        # force cast a generator
        self._extra_instr_handler[instruction_class] = handler

    def add_forbidden_instruction_class(self, instruction_class):
        """add a forbidden instruction class and its handler"""
        self._avoid_instr_classes.add(instruction_class)

    @classmethod
    @log.wrap_call
    def set_default_handler(cls, instruction_class: type, handler: Generator):
        """add a new instruction class to recognize and assign a proper handler"""
        cls._supp_instr_handler[instruction_class] = handler
        if instruction_class in cls._excl_instr_classes:
            cls._excl_instr_classes.remove(instruction_class)

    @classmethod
    @log.wrap_call
    def set_default_forbidden(cls, instruction_class):
        """remind that this kind of instruction is not supported"""
        cls._excl_instr_classes.add(instruction_class)
        if instruction_class in cls._supp_instr_handler:
            del cls._supp_instr_handler[instruction_class]

    @log.wrap_call
    def match_instruction(self, instruction):
        """find a matching container for instruction"""
        for elder in instruction.__class__.__mro__:
            # note: mro contains type(self) and then all parents

            # # check local classes
            if elder in self._avoid_instr_classes:
                return None
            if elder in self._extra_instr_handler:
                return self._extra_instr_handler[elder]

            # check defaults
            if elder in type(self)._excl_instr_classes:
                return None
            if elder in type(self)._supp_instr_handler:
                return type(self)._supp_instr_handler[elder]
        return None

    @log.wrap_call
    def request_temp(
        self, container, name, generating, autorequire=True, **genargs
    ):
        """request a temporary variable"""
        variable = container.context.namespace.request_temp(
            generating, name, origin=container, **genargs
        )
        if autorequire:
            container.requires(variable)
        return variable

